"""Diff item models, dependency ordering, filtering, and SQL script assembly."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import StrEnum
from typing import Any

from pgadmin_schemadiff.config import OutputFilterOptions
from pgadmin_schemadiff.exceptions import PgAdminRuntimeError

SCRIPT_HEADER = (
    "-- This script was generated by the Schema Diff utility in pgAdmin 4.\n"
    "-- Due to circular dependencies, the order in which Schema Diff writes objects may not be optimal\n"
    "-- and manual changes to the script may be required to ensure changes are applied in the correct order.\n"
    "-- Please report any issues along with steps to reproduce.\n"
)


class DiffStatus(StrEnum):
    """Comparison result statuses produced by pgAdmin 4 Schema Diff."""

    IDENTICAL = "Identical"
    DIFFERENT = "Different"
    SOURCE_ONLY = "Source Only"
    TARGET_ONLY = "Target Only"


@dataclass
class DiffItem:
    """Normalized representation of a single pgAdmin 4 Schema Diff comparison item."""

    id: int
    node_type: str
    label: str
    title: str
    status: DiffStatus
    oid: int | None = None
    group_name: str = "Schema Objects"
    source_ddl: str = ""
    target_ddl: str = ""
    diff_ddl: str | None = None
    dependencies: list[dict[str, Any]] = field(default_factory=list)
    source_schema_name: str | None = None
    depend_level: int = 1

    @classmethod
    def from_pgadmin_dict(cls, raw: dict[str, Any]) -> DiffItem:
        """Create a :class:`DiffItem` from a raw dictionary returned by pgAdmin 4."""
        raw_status = raw.get("status")
        try:
            status = DiffStatus(raw_status)
        except ValueError as exc:
            raise PgAdminRuntimeError(
                f"Unexpected Schema Diff status from pgAdmin 4: {raw_status!r}"
            ) from exc

        return cls(
            id=int(raw["id"]),
            node_type=str(raw.get("type", "")),
            label=str(raw.get("label", "")),
            title=str(raw.get("title", "")),
            status=status,
            oid=raw.get("oid"),
            group_name=str(raw.get("group_name") or "Schema Objects"),
            source_ddl=raw.get("source_ddl") or "",
            target_ddl=raw.get("target_ddl") or "",
            diff_ddl=raw.get("diff_ddl"),
            dependencies=list(raw.get("dependencies") or []),
            source_schema_name=raw.get("source_schema_name"),
        )

    def to_dict(self) -> dict[str, Any]:
        """Serialize this item to a JSON-compatible dictionary."""
        return {
            "id": self.id,
            "node_type": self.node_type,
            "label": self.label,
            "title": self.title,
            "status": self.status.value,
            "oid": self.oid,
            "group_name": self.group_name,
            "source_ddl": self.source_ddl,
            "target_ddl": self.target_ddl,
            "diff_ddl": self.diff_ddl,
            "dependencies": self.dependencies,
            "source_schema_name": self.source_schema_name,
            "depend_level": self.depend_level,
        }


@dataclass
class DiffResult:
    """Complete result of a schema diff run."""

    script: str
    items: list[DiffItem]
    all_items: list[DiffItem]

    def to_dict(self) -> dict[str, Any]:
        """Serialize the diff result to a JSON-compatible dictionary."""
        return {
            "script": self.script,
            "items": [item.to_dict() for item in self.items],
            "summary": {
                "total": len(self.all_items),
                "filtered": len(self.items),
                "source_only": sum(
                    1 for item in self.all_items if item.status == DiffStatus.SOURCE_ONLY
                ),
                "target_only": sum(
                    1 for item in self.all_items if item.status == DiffStatus.TARGET_ONLY
                ),
                "different": sum(
                    1 for item in self.all_items if item.status == DiffStatus.DIFFERENT
                ),
                "identical": sum(
                    1 for item in self.all_items if item.status == DiffStatus.IDENTICAL
                ),
            },
        }


def compute_depend_levels(items: list[DiffItem]) -> list[DiffItem]:
    """Compute dependency levels using pgAdmin 4's reverse-dependency algorithm.

    Any object that another object depends on gets a strictly higher
    ``depend_level`` so that emitting levels highest-first writes dependencies
    before dependents. Circular references are broken by treating the active
    node as level 1 for the back-edge.
    """
    oid_to_item: dict[int, DiffItem] = {
        item.oid: item for item in items if item.oid is not None
    }
    dependents: dict[int, list[DiffItem]] = {}

    for item in items:
        for dep in item.dependencies:
            dep_oid = dep.get("oid") if isinstance(dep, dict) else None
            if dep_oid is None:
                continue
            dependency_item = oid_to_item.get(dep_oid)
            if dependency_item is not None:
                dependents.setdefault(dependency_item.id, []).append(item)

    levels: dict[int, int] = {}
    resolving: set[int] = set()

    def level_of(item: DiffItem) -> int:
        if item.id in levels:
            return levels[item.id]
        if item.id in resolving:
            return 1

        resolving.add(item.id)
        level = 1
        for dependent in dependents.get(item.id, ()):
            level = max(level, level_of(dependent) + 1)
        resolving.remove(item.id)
        levels[item.id] = level
        return level

    for item in items:
        item.depend_level = level_of(item)

    return items


def filter_items(
    items: list[DiffItem],
    output_filter: OutputFilterOptions,
) -> list[DiffItem]:
    """Filter diff items according to :class:`OutputFilterOptions`."""
    selected = output_filter.selected_statuses()
    return [item for item in items if item.status.value in selected]


def generate_diff_script(
    items: list[DiffItem],
    output_filter: OutputFilterOptions,
) -> str:
    """Assemble the final transaction-wrapped migration SQL script."""
    compute_depend_levels(items)
    selected = output_filter.selected_statuses()

    script_by_level: dict[int, list[str]] = {}
    for item in items:
        if item.status.value not in selected:
            continue
        if item.diff_ddl is None or not item.diff_ddl.strip():
            continue

        level_scripts = script_by_level.setdefault(item.depend_level, [])
        if item.source_schema_name:
            schema_query = f"\nCREATE SCHEMA IF NOT EXISTS {item.source_schema_name};\n"
            if schema_query not in level_scripts:
                level_scripts.append(schema_query)
        level_scripts.append(item.diff_ddl)

    chunks = [
        "\n".join(script_by_level[level])
        for level in sorted(script_by_level.keys(), reverse=True)
        if script_by_level[level]
    ]
    if chunks:
        body = "\n" + "\n\n".join(chunks) + "\n\n"
    else:
        body = "\n"

    return f"{SCRIPT_HEADER}BEGIN;\n{body}END;\n"
